/**
 * frontend/src/api_service.js - SERVICE API CORRIGÉ
 * ✅ Synchronisé avec backend
 */

import authService from './auth_service';

const API_BASE_URL = 'http://localhost:8000';

/**
 * ============ UTILS ============
 */
const cleanBase64 = (base64String) => {
  if (!base64String) return '';
  if (base64String.startsWith('data:')) {
    return base64String.split(',')[1];
  }
  return base64String;
};

/**
 * ============ STUDENTS API ============
 */
export const studentsAPI = {
  /**
   * ✅ ENROLL: Upload image base64
   */
  enrollFromImage: async (name, email, file) => {
    try {
      const reader = new FileReader();

      return new Promise((resolve, reject) => {
        reader.onload = async (e) => {
          try {
            const imageBase64 = e.target.result;

            const response = await authService.api.post(
              '/students/enroll_from_image/',
              {
                name,
                email: email || '',
                image_base64: cleanBase64(imageBase64)
              }
            );

            console.log('✅ [ENROLL] Success:', response.data);
            resolve({ success: true, data: response.data });
          } catch (error) {
            const message = error.response?.data?.error || 'Erreur d\'enrôlement';
            console.error('❌ [ENROLL] Failed:', message);
            reject({ success: false, error: message, response: error.response });
          }
        };

        reader.onerror = () => {
          reject({ success: false, error: 'Erreur de lecture du fichier' });
        };

        reader.readAsDataURL(file);
      });
    } catch (error) {
      console.error('❌ [ENROLL] Error:', error);
      throw error;
    }
  },

  /**
   * ✅ GET ALL STUDENTS
   */
  getAll: async () => {
    try {
      const response = await authService.api.get('/students/');
      return { success: true, data: response.data };
    } catch (error) {
      console.error('❌ [STUDENTS] Fetch failed:', error);
      return { success: false, error: 'Erreur de récupération' };
    }
  },

  /**
   * ✅ SEARCH STUDENTS
   */
  search: async (query) => {
    try {
      const response = await authService.api.post('/students/search/', {
        query,
      });

      console.log('✅ [SEARCH] Results:', response.data);
      return { success: true, data: response.data };
    } catch (error) {
      console.error('❌ [SEARCH] Failed:', error);
      return { success: false, error: 'Erreur de recherche' };
    }
  },

  /**
   * ✅ GET STATS
   */
  getStats: async () => {
    try {
      const response = await authService.api.get('/students/stats/');
      return { success: true, data: response.data };
    } catch (error) {
      console.error('❌ [STATS] Failed:', error);
      return { success: false, error: 'Erreur de stats' };
    }
  },
};

/**
 * ============ ATTENDANCE API ============
 */
export const attendanceAPI = {
  /**
   * ✅ RECOGNIZE: Reconnaissance faciale
   */
  recognize: async (imageBase64) => {
    try {
      const cleanedBase64 = cleanBase64(imageBase64);

      const response = await authService.api.post('/attendance/recognize/', {
        image_base64: cleanedBase64,
      });

      console.log('✅ [RECOGNIZE] Response:', response.data);
      return { success: true, data: response.data };
    } catch (error) {
      // 404 = pas de match (normal)
      if (error.response?.status === 404) {
        return { success: false, data: error.response.data, isNoMatch: true };
      }

      const message = error.response?.data?.error || 'Erreur de reconnaissance';
      console.error('❌ [RECOGNIZE] Failed:', message);
      return { success: false, error: message };
    }
  },

  /**
   * ✅ GET TODAY'S LOG
   */
  getTodayLog: async () => {
    try {
      const response = await authService.api.get('/attendance/');
      return { success: true, data: response.data };
    } catch (error) {
      console.error('❌ [TODAY_LOG] Failed:', error);
      return { success: false, error: 'Erreur de log' };
    }
  },

  /**
   * ✅ GET STATS
   */
  getStats: async () => {
    try {
      const response = await authService.api.get('/attendance/stats/');
      return { success: true, data: response.data };
    } catch (error) {
      console.error('❌ [ATTENDANCE_STATS] Failed:', error);
      return { success: false, error: 'Erreur de stats' };
    }
  },

  /**
   * ✅ GET STATUS
   */
  getStatus: async () => {
    try {
      const response = await authService.api.get('/attendance/status/');
      return { success: true, data: response.data };
    } catch (error) {
      console.error('❌ [STATUS] Failed:', error);
      return { success: false, error: 'Erreur de statut' };
    }
  },

  /**
   * ✅ GET HISTORY
   */
  getHistory: async (studentId, days = 30) => {
    try {
      const response = await authService.api.get('/attendance/student_history/', {
        params: { student_id: studentId, days },
      });

      return { success: true, data: response.data };
    } catch (error) {
      console.error('❌ [HISTORY] Failed:', error);
      return { success: false, error: 'Erreur d\'historique' };
    }
  },
};

export default {
  studentsAPI,
  attendanceAPI,
};
